"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["13218"],{97368(e){e.exports=JSON.parse('{"id":"V4-077","slug":"sarbanes-oxley-act","term":"Sarbanes-Oxley Act","also_known_as":[],"difficulty":"Advanced","definition":"The Sarbanes-Oxley Act is a United States law passed in 2002 that strengthened corporate governance, financial reporting and auditing requirements for public companies, in response to accounting scandals such as Enron and WorldCom.","explanation":["The act, often called SOX, was named after its sponsors, Senator Paul Sarbanes and Representative Michael Oxley. It introduced major reforms aimed at restoring investor confidence.","Key provisions include requiring chief executives and chief financial officers to personally certify the accuracy of financial reports; requiring management to assess, and larger companies\u2019 auditors to test, internal controls over financial reporting; creating the Public Company Accounting Oversight Board to regulate auditors; strengthening auditor independence by restricting non-audit services; requiring independent audit committees; and increasing penalties for fraud.","For example, under the act, a chief financial officer who knowingly certifies false financial statements can face heavy fines and imprisonment.","The act improved the reliability of financial reporting and internal controls, but critics argued that compliance costs, especially for internal control testing, were high, particularly for smaller companies. Some smaller companies are exempt from parts of the requirements. Many other countries introduced similar reforms, sometimes described as their own versions of SOX."],"note":"","total":1725,"prev":{"slug":"sanctions-screening","term":"Sanctions Screening"},"next":{"slug":"saving-rate","term":"Saving Rate"}}')}}]);